import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { CarDto, ManufacturerDto, ManufacturerRatingDto, RatingDto } from './models';

const ROOT = '/api';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getManufacturers(): Observable<ManufacturerDto[]> {
    return this.http.get<ManufacturerDto[]>(`${ROOT}/manufacturers`);
  }
  saveManufacturer(m: ManufacturerDto): Observable<ManufacturerDto> {
    return this.http.post<ManufacturerDto>(`${ROOT}/manufacturers`, m);
  }
  deleteManufacturer(id: number): Observable<void> {
    return this.http.delete<void>(`${ROOT}/manufacturers/${id}`);
  }
  getAverageRatings(): Observable<ManufacturerRatingDto[]> {
    return this.http.get<ManufacturerRatingDto[]>(`${ROOT}/manufacturers/ratings`);
  }

  getRatings(): Observable<RatingDto[]> {
    return this.http.get<RatingDto[]>(`${ROOT}/ratings`);
  }
  saveRating(r: RatingDto): Observable<RatingDto> {
    return this.http.post<RatingDto>(`${ROOT}/ratings`, r);
  }
  deleteRating(id: number): Observable<void> {
    return this.http.delete<void>(`${ROOT}/ratings/${id}`);
  }

  getCars(): Observable<CarDto[]> {
    return this.http.get<CarDto[]>(`${ROOT}/cars`, { params: { offset: 0, limit: -1 } });
  }
}
