import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../api.service';
import { MessageService } from '../message.service';
import { ManufacturerDto } from '../models';

@Component({
  selector: 'app-manufacturer',
  standalone: true,
  imports: [FormsModule],
  templateUrl: './manufacturer.component.html',
  styleUrl: './manufacturer.component.css',
})
export class ManufacturerComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  protected readonly manufacturers = signal<ManufacturerDto[]>([]);
  /** Manufacturer being edited in the popup; null when the popup is closed. */
  protected readonly editing = signal<ManufacturerDto | null>(null);
  /** The manufacturer from the table being edited (undefined when creating). */
  private editingOriginal: ManufacturerDto | undefined;

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (list) => this.manufacturers.set(list),
      error: () => this.messages.error('Failed to load the manufacturers.'),
    });
  }

  protected onCreate(): void {
    this.editingOriginal = undefined;
    this.editing.set({ name: '', cars: [] });
  }

  protected onEdit(m: ManufacturerDto): void {
    this.editingOriginal = m;
    this.editing.set({ ...m });
  }

  protected onClose(): void {
    this.editing.set(null);
  }

  protected setName(name: string): void {
    const current = this.editing();
    if (current) {
      this.editing.set({ ...current, name });
    }
  }

  protected onSave(): void {
    const dto = this.editing();
    if (!dto) {
      return;
    }
    this.api.saveManufacturer(dto).subscribe({
      next: (saved) => {
        this.messages.success('Manufacturer saved.');
        const original = this.editingOriginal;
        this.manufacturers.update((list) =>
          original ? list.map((m) => (m === original ? saved : m)) : [...list, saved],
        );
        this.editing.set(null);
      },
      error: () => this.messages.error('Failed to save the manufacturer.'),
    });
  }

  protected onDelete(m: ManufacturerDto): void {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) {
      return;
    }
    this.api.deleteManufacturer(m.id as number).subscribe({
      next: () => this.manufacturers.update((list) => list.filter((x) => x !== m)),
      error: () => this.messages.error('Failed to delete the manufacturer.'),
    });
  }
}
