import { Injectable, signal } from '@angular/core';

export type MessageStyle = 'success' | 'error';

export interface Message {
  key: number;
  text: string;
  style: MessageStyle;
}

const DEFAULT_CLOSE_DELAY = 5000;

@Injectable({ providedIn: 'root' })
export class MessageService {
  readonly messages = signal<Message[]>([]);
  private nextKey = 0;

  success(text: string): void {
    this.add(text, 'success');
  }

  error(text: string): void {
    this.add(text, 'error');
  }

  close(key: number): void {
    this.messages.update((list) => list.filter((m) => m.key !== key));
  }

  private add(text: string, style: MessageStyle): void {
    const key = this.nextKey++;
    this.messages.update((list) => [...list, { key, text, style }]);
    setTimeout(() => this.close(key), DEFAULT_CLOSE_DELAY);
  }
}
