export interface ManufacturerDto {
  id?: number | null;
  name: string;
  cars?: CarDto[];
}

export interface CarPropertiesDto {
  [key: string]: unknown;
}

export interface CarDto {
  id?: number | null;
  model: string;
  manufacturer?: ManufacturerDto | null;
  ratings?: RatingDto[];
  carProperties?: CarPropertiesDto | null;
}

export interface RatingDto {
  id?: number | null;
  rating: number | null;
  car: CarDto | null;
}

export interface ManufacturerRatingDto {
  manufacturer: string;
  rating: number;
}

/** Same text as RatingDto.toString() in the GWT sources: "Manufacturer/model". */
export function ratingCarLabel(r: RatingDto): string {
  const car = r.car;
  if (car) {
    // A car whose manufacturer was deleted still keeps the "Manufacturer/model" shape.
    return (car.manufacturer ? car.manufacturer.name : 'Unknown') + '/' + car.model;
  }
  return r.id != null ? String(r.id) : '';
}

export function carLabel(c: CarDto): string {
  return (c.manufacturer ? c.manufacturer.name + ' ' : '') + c.model;
}
