import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../api.service';
import { MessageService } from '../message.service';
import { CarDto, RatingDto, carLabel, ratingCarLabel } from '../models';

@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [FormsModule],
  templateUrl: './rating.component.html',
  styleUrl: './rating.component.css',
})
export class RatingComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  protected readonly ratings = signal<RatingDto[]>([]);
  protected readonly cars = signal<CarDto[]>([]);
  protected readonly formOpen = signal(false);
  protected selectedCar: CarDto | null = null;
  protected ratingValue: number | null = null;

  protected readonly carLabel = carLabel;
  protected readonly ratingCarLabel = ratingCarLabel;

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (list) => this.ratings.set(list),
      error: () => this.messages.error('Failed to load the ratings.'),
    });
  }

  protected onCreate(): void {
    this.api.getCars().subscribe({
      next: (cars) => {
        this.cars.set(cars);
        this.selectedCar = cars.length ? cars[0] : null;
        this.ratingValue = null;
        this.formOpen.set(true);
      },
      error: () => this.messages.error('Failed to load the cars.'),
    });
  }

  protected onClose(): void {
    this.formOpen.set(false);
  }

  protected onSave(): void {
    const dto: RatingDto = { car: this.selectedCar, rating: this.ratingValue };
    this.api.saveRating(dto).subscribe({
      next: (saved) => {
        this.messages.success('Rating saved.');
        this.ratings.update((list) => [...list, saved]);
        this.formOpen.set(false);
      },
      error: () => this.messages.error('Failed to save the rating.'),
    });
  }

  protected onDelete(r: RatingDto): void {
    if (!window.confirm('Are you sure you want to delete' + ratingCarLabel(r) + '?')) {
      return;
    }
    this.api.deleteRating(r.id as number).subscribe({
      next: () => this.ratings.update((list) => list.filter((x) => x !== r)),
      error: () => this.messages.error('Failed to delete the rating.'),
    });
  }
}
